// ============================================================
// LinkedIn Job Alert Email Parser
// ============================================================
const results = [];
const seenIds = new Set();

for (const item of $input.all()) {
  const emailId = item.json.id || '';
  const subject = item.json.subject || '';
  const html = item.json.html || item.json.textHtml || '';
  const text = item.json.text || item.json.textPlain || '';

  const subjectLower = subject.toLowerCase();
  if (subjectLower.includes('your application') ||
      subjectLower.includes('application was sent') ||
      subjectLower.includes('problem with your')) {
    continue;
  }

  const urlRegex = /href=["']([^"']*linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)[^"']*)["']/gi;
  const textUrlRegex = /(https?:\/\/(?:www\.)?linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)[^\s]*)/gi;

  const content = html || text;
  const regex = html ? urlRegex : textUrlRegex;
  let match;

  while ((match = regex.exec(content)) !== null) {
    const fullUrl = match[1];
    const jobId = match[2];

    if (!jobId || seenIds.has(jobId)) continue;
    seenIds.add(jobId);

    let title = 'Unknown Title';
    if (html) {
      const titleRegex = new RegExp(
        `href=["'][^"']*jobs/view/${jobId}[^"']*["'][^>]*>([^<]+)<`,
        'i'
      );
      const titleMatch = titleRegex.exec(html);
      if (titleMatch) title = titleMatch[1].trim();
    }

    results.push({
      json: {
        linkedin_job_id: jobId,
        title: title,
        company: '',
        location: '',
        workplace_type: '',
        linkedin_url: `https://www.linkedin.com/jobs/view/${jobId}/`,
        source_email_id: emailId,
        source_email_subject: subject,
        discovered_at: new Date().toISOString()
      }
    });
  }
}

if (results.length === 0) {
  results.push({ json: { _no_jobs: true, message: 'No new jobs found in emails' } });
}

return results;

