// ============================================================
// Parse GPT Assessment & Compute Deterministic Policy Decision
// ============================================================
const items = $input.all();
const results = [];

for (const item of items) {
  let analysis;
  try {
    const response = item.json.choices?.[0]?.message?.content || '{}';
    analysis = JSON.parse(response);
  } catch (e) {
    analysis = { fit_score: 0, decision: 'SKIP', explanation: 'Failed to parse AI response' };
  }

  // GPT Semantic Assessment
  const fitScore = typeof analysis.fit_score === 'number' ? analysis.fit_score : 0;
  const riskFlags = Array.isArray(analysis.risk_flags) ? analysis.risk_flags : [];

  // Deterministic Workflow Decision Policy
  let policyDecision = 'SKIP';
  if (fitScore >= 80) policyDecision = 'APPLY';
  else if (fitScore >= 65) policyDecision = 'REVIEW';
  else policyDecision = 'SKIP';

  // Hard rejection override if risk flags indicate hard disqualification
  const hasHardRejection = riskFlags.some(flag => 
    flag.toLowerCase().includes('citizenship') || 
    flag.toLowerCase().includes('security clearance') ||
    flag.toLowerCase().includes('native german')
  );
  if (hasHardRejection) policyDecision = 'SKIP';

  analysis.policy_decision = policyDecision;

  results.push({
    json: {
      job_id: item.json.job_id || 1,
      analysis: analysis,
      fit_score: fitScore,
      gpt_recommended_decision: analysis.decision,
      policy_decision: policyDecision
    }
  });
}

return results;

